tape = list('1011')
i = 0
state = 'go_right'
while True:
    if state == 'go_right':
        i = i + 1
        if i == len(tape):
            state = 'go_left'
            i = i - 1
    elif state == 'go_left':
        if tape[i] == '1':
            tape[i] = '0'
            i = i - 1
            if i < 0:
                tape.insert(0, '1')
                break
        else:
            tape[i] = '1'
            break
print(''.join(tape))
